import math


M = 26
_ALPHABET = "abcdefghijklmnopqrstuvwxyz"


def _mmi(a, m):
    """Modular multiplicative inverse of a mod m (m is small here)."""
    for x in range(1, m):
        if (a * x) % m == 1:
            return x
    raise ValueError("a and m must be coprime.")


def encode(plain_text, a, b):
    if math.gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")

    cleaned = [ch.lower() for ch in plain_text if ch.isalnum()]
    out = []
    for ch in cleaned:
        if ch.isdigit():
            out.append(ch)
        else:
            x = _ALPHABET.index(ch)
            out.append(_ALPHABET[(a * x + b) % M])

    return " ".join("".join(out)[i:i + 5] for i in range(0, len(out), 5)) if out else ""


def decode(ciphered_text, a, b):
    if math.gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")

    a_inv = _mmi(a, M)
    cleaned = [ch for ch in ciphered_text if ch.isalnum()]
    out = []
    for ch in cleaned:
        if ch.isdigit():
            out.append(ch)
        else:
            y = _ALPHABET.index(ch.lower())
            out.append(_ALPHABET[(a_inv * (y - b)) % M])

    return "".join(out)
